// Preter prête le titre au membre.
func (s *Stock) Preter(titre, membre string) error {
	if !s.dispo[titre] {
		return fmt.Errorf("prêt de %q : %w", titre, ErrIndisponible)
	}
	if s.emprunts[membre] >= 2 {
		return &ErreurQuota{Membre: membre, Max: 2}
	}
	s.dispo[titre] = false
	s.emprunts[membre]++
	return nil
}
